func (c *Config) validate() error {
	if c.Database.URL == "" && (c.Database.Protocol != 0 || c.Database.Host != "" || c.Database.Name != "" || c.Database.Port != 0 || c.Database.User != "" || c.Database.Password != "") {
		if err := c.validateDatabase(); err != nil { return err }
	}
	if c.Server.Protocol == HTTPS {
		if c.Server.CertFile == "" {
			return errors.New("cert_file cannot be empty when using HTTPS")
		}

		if c.Server.CertKey == "" {
			return errors.New("cert_key cannot be empty when using HTTPS")
		}

		if _, err := os.Stat(c.Server.CertFile); os.IsNotExist(err) {
			return fmt.Errorf("cannot find TLS cert_file at %q", c.Server.CertFile)
		}

		if _, err := os.Stat(c.Server.CertKey); os.IsNotExist(err) {
			return fmt.Errorf("cannot find TLS cert_key at %q", c.Server.CertKey)
		}
	}

	return nil
}

func (c *Config) validateDatabase() error {
	if c.Database.URL == "" {
		d := c.Database
		if d.Protocol == 0 {
			return errors.New("db.protocol is required when db.url is not set")
		}
		if d.Protocol < DatabaseProtocolSQLite || d.Protocol > DatabaseProtocolMySQL {
			return fmt.Errorf("invalid db.protocol %d: expected one of sqlite, postgres, mysql", d.Protocol)
		}
		if d.Protocol == DatabaseProtocolSQLite {
			if d.Name == "" {
				return errors.New("db.name (SQLite database path) is required when db.url is not set")
			}
		} else {
			if d.Name == "" {
				return errors.New("db.name is required when db.url is not set")
			}
			if d.Host == "" {
				return errors.New("db.host is required when db.url is not set")
			}
		}
	}
	return nil
